class Counter {
  constructor(start) {
    this.value = start;
  }

  bump() {
    this.value += 1;
    return this.value;
  }
}

function countUp(start, times) {
  const counter = new Counter(start);
  for (let i = 0; i < times; i++) {
    counter.bump();
  }
  return counter.value;
}

