class Tally {
  constructor(start) {
    this.total = start;
    this.add = (n) => {
      this.total += n;
      return this.total;
    };
  }
}

function sumWith(start, numbers) {
  const tally = new Tally(start);
  const add = tally.add;
  for (const n of numbers) {
    add(n);
  }
  return tally.total;
}

