class Pack {
  constructor(items) {
    this.items = items;
  }

  get weight() {
    return this.items.length * 2;
  }
}

class HeavyPack extends Pack {
  constructor(items, padding) {
    super(items);
    this.padding = padding;
  }

  get weight() {
    return super.weight + this.padding;
  }

  static bare(padding) {
    return new HeavyPack([], padding);
  }
}

function packWeights(items, padding) {
  return [new HeavyPack(items, padding).weight, HeavyPack.bare(padding).weight];
}

