exam.solution:
class Inventory {
  constructor(items) {
    this.items = items;
  }

  get total() {
    let sum = 0;
    for (const item of this.items) {
      sum += item.qty;
    }
    return sum;
  }

  add(name, qty) {
    this.items.push({ name: name, qty: qty });
    return this.total;
  }

  static empty() {
    return new Inventory([]);
  }
}

function stockReport(items, name, qty) {
  const inventory = new Inventory(items);
  inventory.add(name, qty);
  return [inventory.total, Inventory.empty().total];
}
